window.RP_SESSION={"id":"S-f44f6d678672","messages":[{"id":"RP-III-0119783","time":"2026-07-14T03:06:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"그래도 밥은 먹고 살아야죠","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119784","time":"2026-07-14T03:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"오늘은 특별히 준비된 식재료가 없어서 오트밀을 물에 불리고. 염장한 돼지고기 한 조각과 밖에서 뜯은 쇠비름, 민들레 잎을 가지고 요리를 해야 한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119785","time":"2026-07-14T03:20:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"냄비 바닥에서 염장한 돼지고기를 굴려가며 굽자 기름기와 고소한 향기가 부엌에 퍼진다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119786","time":"2026-07-14T03:21:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"갈색으로 색이 날 때 쯤 맥주를 살짝 넣어 바닥에 붙은 갈색 마이야르 덩어리를 불리고","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119787","time":"2026-07-14T03:21:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"불린 오트밀과 쇠비름, 민들레 잎을 차례로 넣어 주걱으로 젓는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119788","time":"2026-07-14T03:22:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"여러 사람 먹을 몫은 아니지만 혼자 먹기 딱 좋은 오트밀 죽이 완성된다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119789","time":"2026-07-14T03:22:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119790","time":"2026-07-14T03:22:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 8 = 8\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0119791","time":"2026-07-14T03:23:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"생각보다 괜찮은 맛이 나는 오트밀 죽을 먹으며 레마는 잠시 하루 종일 일한 피로를 푼다. 그뿐.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119792","time":"2026-07-14T04:11:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"아, 좋아.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119793","time":"2026-07-14T04:11:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"아직 잠을 자기엔, 도적의 밤은 길다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119794","time":"2026-07-14T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"먹은 식기와 조리도구를 뒷정리 해 두고 훈련장으로 향한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119795","time":"2026-07-14T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119796","time":"2026-07-14T04:16:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 지능 판정 :\n[4] + [1] = [5]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0119797","time":"2026-07-14T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"시작이 안좋아... 하지만?","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119798","time":"2026-07-14T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119799","time":"2026-07-14T04:16:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[6] + [3] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0119800","time":"2026-07-14T04:16:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"딱! 꽂히는 소리와 함께 짧뚱한 작은 화살이 과녁에 명중한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119801","time":"2026-07-14T04:20:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"경쾌하고 명량한 소리가 수 차례 연달아 훈련장에 울려퍼진다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119802","time":"2026-07-14T04:24:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119803","time":"2026-07-14T04:24:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[7] + [3] = [10]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0119804","time":"2026-07-14T04:24:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마지막 한 발 까지 예외 없이 모두 명중시킨다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119805","time":"2026-07-14T04:24:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"시원하군!","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119806","time":"2026-07-14T04:50:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"활 다음은...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119807","time":"2026-07-14T04:50:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"검","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119808","time":"2026-07-14T04:50:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 이번엔 곡도를 들고 허수아비 앞에 선다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119809","time":"2026-07-14T04:51:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119810","time":"2026-07-14T04:51:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[6, 1, 4] + [3, 2]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-III-0119811","time":"2026-07-14T04:51:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"가상의 상대로 떠올린 적은... 갑옷을 입지 않고 똑같은 검을 든 채 서 있는 적.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119812","time":"2026-07-14T04:51:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"잠시 팽팽하게 대치를 이어나가다 레마가 먼저 검을 휘두른다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119813","time":"2026-07-14T04:51:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119814","time":"2026-07-14T04:51:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[2, 2, 4] + [2, 3]\n성공수 : [ 1 ]","characters":[]},{"id":"RP-III-0119815","time":"2026-07-14T04:52:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"가상의 상대는 상상 속의 검을 휘둘러 레마의 검을 쳐내고, 그대로 연속 공격을 하며 압박한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119816","time":"2026-07-14T04:52:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119817","time":"2026-07-14T04:52:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[4, 4, 1] + [3, 4]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-III-0119818","time":"2026-07-14T04:53:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만 레마는 결정적인 순간 적의 몸이 앞으로 쏠린 틈에 어깨에 칼을 휘두른다. 칼은 얕지만 정확하게 적의 어깨를 스친다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119819","time":"2026-07-14T04:53:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119820","time":"2026-07-14T04:53:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[3, 3, 3] + [4, 4]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-III-0119821","time":"2026-07-14T04:53:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"한 번 승기를 잡은 레마지만 바로 끝나지는 않는다. 적은 여전히 위협적인 검을 들고 있다고 상상한다. 대치가 이어지다...","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119822","time":"2026-07-14T04:53:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119823","time":"2026-07-14T04:53:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[2, 2, 4] + [2, 4]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-III-0119824","time":"2026-07-14T04:56:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"검과 검이 부딪힌다. 두 쇳덩이가 상상 속에서 격렬하게 불꽃을 튀기며 거칠고 날카로운 소리를 낸다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119825","time":"2026-07-14T04:56:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119826","time":"2026-07-14T04:56:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[3, 2, 6] + [6, 6]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-III-0119827","time":"2026-07-14T04:57:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"하지만 어깨를 다친 적의 검격은 오래 가지 못했다. 레마의 검이 아름다운 궤적을 그리며 적의... 아니, 허수아비의 목을 베어 떨어트린다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119828","time":"2026-07-14T04:58:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"상상 속 적의 검격이 멈추고 시체가 쓰러진다. 레마는 거기까지 지켜보다 망가진 허수아비를 치우고 다시 세운다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119829","time":"2026-07-14T05:05:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 땀으로 범벅이 된 이마를 자그마한 손수건으로 슥 닦는다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119833","time":"2026-07-17T01:23:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"웬 갈색머리 청년이 늦은 시간 훈련장을 찾아옵니다. \n잠이 안 온 것인지, 안면에 내려앉은 피곤해하는 기색이 어렴풋이 보입니다.\n그는 먼저 와 있는 레마를 한발 늦게 발견합니다.\n\n“...아.”\n\n발길이 잠시 멈춥니다.\n이 시간에 다른 누군가 시설을 쓰고 있을 지 몰랐다는 눈치입니다.\n\n“실례… 하겠습니다.”\n\n물론 누구나 사용 가능한 공간이었겠지만,\n혼자 지내기를 좋아하는 자들도 있을 법했으니.\n\n“얘는 안 쓰고 계시죠?”\n\n그는 옆의 덩치 큰 허수아비를 가리켰습니다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119834","time":"2026-07-17T01:30:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 어머, 아서 씨 오, 오셨어요? 그건 아, 안 쓰고 있어요. \"\n\n손수건을 고이 접어 놓아두고 물을 한 모금 마시며.\n\n\" 오늘따라 잠이 아, 안 오더라구요. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119835","time":"2026-07-17T01:39:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"아...! 감사합니다. 그... 레마 씨... 맞으시죠?\"\n\n특유의 말더듬을 듣고 나니 전에 마주친 것 같은 기억이 난다.\n\n\"레마 씨도 그랬군요... 검만 몇 번 휘두르고 갈 테니, 너무 신경 쓰시진 마세요.\"\n\n청년은 검을 꺼내들더니 잠시 그녀를 바라봅니다. \n\n\"그... 하시던 거 있으시면 계속 하셔도 괜찮아요.\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119836","time":"2026-07-17T01:39:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"이 늦은 시간에 훈련장에 사람이, 그것도 둘이나 계시네? 어라, 아서 씨다!\n갈비뼈에 온통 붕대를 칭칭 감은 해골이 절뚝거리며 훈련장에 들어옵니다.\n“이 시간에도 훈련을 하시네요?”","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119837","time":"2026-07-17T01:41:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"어머,아마이씨? 아서씨..였나요? 아서씨도 계시는군요? 수박주스님까지?\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119838","time":"2026-07-17T01:41:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 사실 끄, 끝내고 자러 가려고 하, 하긴 했는데... 아서 씨가 하, 하시는 것도 보고 싶네요! \"\n\n특유의 고개를 살짝 옆으로 기울이며 짓는 웃음을 지으며 말한다.","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119839","time":"2026-07-17T01:42:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 제 이름은 수, 수박 주스가 아니라 레마에요. 레마 캐롤라인! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119840","time":"2026-07-17T01:42:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 하하, 어, 어서 와요 아마이 씨. \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119841","time":"2026-07-17T01:42:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"아....죄송합니다... 전 리키라고 해요. 아,아실려나?\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119842","time":"2026-07-17T01:42:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"“아하하... 감사합니다. 볼 건 별로 없겠지만...”\n\n청년은 검을 허수아비에게 겨누었다.\n\n자세를 잡는다. 무게중심은 두 발 중간. 시작은 방어적인 태세를 취한다. 시선은 고정. 깜빡이면 죽는다.\n\n검은 아직 잠잠했다. \n그녀가 그랬듯이, 이자도 나름 상상의 적을, \n혹은 기억 속의 적을 떠올리는 것처럼 보인…\n\n아니다. 오히려 그 반대인가.\n\n동공이 길을 잃었다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119843","time":"2026-07-17T01:43:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"음...아서씨?\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119844","time":"2026-07-17T01:43:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 물론이죠 리, 리키 씨. 간만에 보, 보는 것 같아요! \"","characters":["P-fec1db60d51e"]},{"id":"RP-III-0119845","time":"2026-07-17T01:44:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“레마 씨였나? 오랜만이네요, 헹헹! 다들 늦은 시간인데도 열심이군요..”\n조심스레 구석에 자리를 잡아 앉습니다.\n“에고고..”","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119846","time":"2026-07-17T01:44:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"아마이씨도 훈련하러 오셧나요?\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119847","time":"2026-07-17T01:44:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"저도 하려고 했는데....사람이 넘 많아서 하기 좀 그렇네요..\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119848","time":"2026-07-17T01:45:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“아뇨, 보시다시피 지금 제 몸 상태가 이래서.”\n온통 붕대를 칭칭 감은 갈비뼈를 보여줍니다.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119849","time":"2026-07-17T01:45:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“그냥 뭔가 하루라도 여길 안 오면 좀.. 맘이 불편하달까요!”","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119850","time":"2026-07-17T01:46:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"팔 근육이 살짝 부푼다. 곧 휘두를 듯하다. \n내려칠 듯이 검날이 흔들린다.\n\n멈칫.\n\n“큭…!”\n\n-휙–\n\n자세가 흐트러졌다. 검 끄트머리가 간신히 허수아비의 옷가락을 스쳤다.\n\n“...젠장…!!”\n-챙그랑–!\n\n한두 번 겪어본 것이 아니었는지 검을 떨어트리고 한 발자국 물러나 떨리는 숨을 내쉰다.\n이따금 마른침을 억지로 삼키며 숨을 최대한 골라 보지만 어려워하는 듯하다.\n\n“하아… 큭… 하아…”\n\n잠시 그러다가 옆의 존재들을 다시 기억했는지 돌아본다.\n\n“...아, 죄송합… 니다.”\n\n실력을 뽐내려고 온 것은 아니었지만 어딘가 떨어지는 모습을 보인 것에는 조금 미안한 듯하다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119851","time":"2026-07-17T01:46:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"아서씨?\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119852","time":"2026-07-17T01:47:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"너무 조급해보이시는데...걱정거리 있어요?\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119853","time":"2026-07-17T01:47:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“아서 씨, 헹헹. 미안할 게 뭐 있어요?”\n가만히 앉아 아서를 빤히 쳐다보며 말한다.\n“아서 씬 가만보면 너무 착하고 소심한 면이 있으셔서 문제에요.”","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119854","time":"2026-07-17T01:49:00+09:00","room":"RP III","name":"리키","profile":"리키","identity":"reviewed","type":"dialogue","body":"\"실제 사람이 아녀서 그런가...\"\n\n터벅터벅 걸어가 아서 앞에서며\n\n\"저한테 공격해보세요.\"","characters":["P-bb4b9d047737"]},{"id":"RP-III-0119855","time":"2026-07-17T01:49:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“아, 물론 소심하단게 겁이 많단 건 아닙니다. 의뢰 때 아서 씬 나서는 걸 마다하진 않는 것 같았으니까요. 너무 주변 눈칠 많이 본달까요? 배려심이 너무 깊어서 탈이랄까!”","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119856","time":"2026-07-17T01:51:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"아서에게 너무 한꺼번에, 많은 말들이 들이닥쳤을 지도요.\n그것을 의식한 조는 말을 좀 줄여야겠단 생각을 잠시 했습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119857","time":"2026-07-17T01:51:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"아... 그런가요? 하하...\"\n\n그는 눈앞에 아른거리는 형상을 최대한 무시해보지만 조금 어지러워하는 건 그대로입니다.\n검을 내려놔두고 잠시 앉습니다.\n\n\"좀 연습이나 할려고 왔는데... 죄, 죄송합니다, 리키 씨. 제가 힘이 좀... 빠진 것 같네요.\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119858","time":"2026-07-17T01:53:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"으음, 확실히 아서에게 무슨 일이 있어보이긴 하는군요.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119859","time":"2026-07-17T01:53:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"숙소로 멀어져 가는 말더듬이 여인에게 잠시 고개를 숙여 인사하고는 다시 둘에게 돌아섭니다.\n\"그나저나 아마이 씨, 몸이 왜...\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119860","time":"2026-07-17T01:54:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“아아, 벌집을 처리하는 의뢰를 하다가 그만.. 다들 벌 조심하세요, 헹헹.“\n그러곤 팔을 휘적이며 커다란 원을 그립니다.\n”이~~따시만한 벌 본 적 있어요? 히야.. 진짜 아마이징하게 강해서, 죽을 뻔했다구요.“","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119861","time":"2026-07-17T01:57:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"붕대가 감긴 뼈를 보며 언데드의 뼈가 재생될 수 있는지 의아해합니다.\n\n\"우와, 전에 그런 벌에 대해 들어본 것 같은데...\"\n\n아마이 조의 나름 밝은 모습에 감사하게 느낍니다.\n동공의 흔들림이 잠시 침착됩니다.\n\n\"다행히 무사하시군요. 그래도 당분간 임무는 좀... 쉬시는 게...\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119862","time":"2026-07-17T01:58:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“헹헹, 아무래도 그래야겠죠. 빨리 나아서 다시 훈련과 의뢰를 시작하고 싶네요.“\n…낫는 거 맞겠지, 이거?\n”아, 그보다 아서 씨, 뭔 일 있어요? 안색이 좋지가 않네요.“","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119863","time":"2026-07-17T02:01:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"아, 벼, 별 거 아닙니다. 걱정할 필요가... 큭...!\"\n\n욱신거리는 어깨를 부여잡습니다.\n개미핥기 데미간 의뢰 때 괴물에게 당한 곳이겠군요.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119864","time":"2026-07-17T02:02:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"잠시 동공이 다시 흔들리지만 억지로 진정시키려고 시도합니다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119865","time":"2026-07-17T02:02:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"놀라며 저절로 자리에서 일어납니다.\n“어우어우, 많이 다치셨나본데요! 아서 씨야말로 쉬셔야 하는 거 아닙니까..?!”\n아차, 다친 상태에서 너무 갑자기 움직인 탓일까, 조의 다리에서 섬뜩하게 뚜두둑 소리가 납니다.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119866","time":"2026-07-17T02:02:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“아이코, 훈련장에 뭔 환자밖에 없네요, 헹헹..”","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119867","time":"2026-07-17T02:07:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"...아마이 씨도... 아하... 뭐, 모험가 처지가 다 그렇겠죠, 뭐.\"\n\n그래도 걱정이 되는 듯합니다. 같이 전투에 나갔던 동료인 만큼 아마이를 잃는 건 끔찍한 상상인 듯합니다.\n\n\"앉으세요. 뭐... 제 걱정은 하지 마세요. 전 잘 나으니...\"\n\n말이 언데드에게 상처가 될 수도 있다고 미처 생각하지 못한 듯합니다.\n\n\"아, 제 말은, 그게, 인간과 언데드가 다르다는 게 아니고...! 그, 그리고 언데드는 약골이라는 것도 아니라, 그... 그냥...\"\n\n방금의 여인처럼 말을 더듬으며 수습하려 합니다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119868","time":"2026-07-17T02:09:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“헹헹헹! 걱정 마세요, 아서 씨를 아는 사람이라면, 아서 씨가 남한테 그런 의도로 말할 거라고는 절대 생각 안 할걸요! 걱정해주셔서 고맙네요! 헹헹..“\n아마이 조는 흠뻑 웃음에 적셔 배를 부둥켜 안는 듯한 자셀 취하고, 행복하게 웃으며 말했다.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119869","time":"2026-07-17T02:13:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"아!... 하하...\"\n\n실례가 되었을 법한 말을 그렇게 넘겨주는 아마이를 보며 아서의 피곤했던 표정이 조금 풀린 듯합니다.\n작지만 진심인 미소를 지으며 잠시 땅을 바라보다, 고개를 들어 하늘을 바라봅니다. \n\n\"...아마이 씨, 그... 실례가 될 지 모르겠는데, 뭘 여쭤봐도 될까요?\"\n\n서둘러 덧붙인다.\n\n\"그, 대답하기 좀 그러시면 언제든지 사양하셔도 괜찮고요.\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119870","time":"2026-07-17T02:14:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"다시 천천히, 조심스레 자리에 앉습니다.\n“뭔데요, 편하게 물어보세요!”\n조는 은근히, 아니 어쩌면 꽤 많이 아서를 마음에 들어하는 것 같습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119871","time":"2026-07-17T02:16:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"“아마이 씨는 어쩌다, 그, 되살아나셨나요…?”\n\n청년은 언데드를 만나본 것이 처음인지라 궁금한가 봅니다. \n\n아마이 씨의 이야기를 듣고 싶기도 한가 보네요.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119872","time":"2026-07-17T02:18:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“아아, 저도 자세히는 모릅니다만, 흑마법사에게 죽은 후에 어찌저찌 살아났답니다.”\n굉장히 애매모호한 답이지만, 이전에 션과의 대화를 통해 자신이 어떻게 부활했는지에 대해 가급적 자세히 얘기하면 안 되겠단 생각이 들었기에 어쩔 수 없었습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119873","time":"2026-07-17T02:19:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"그리고 정말로 자세히는 모르기도 하고요.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119874","time":"2026-07-17T02:22:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"아, 그, 그렇군요.\"\n\n아마이 씨가 숨기는 것이 있다면 그만큼 소중하거나 말하기 어려운 내용. 굳이 캐물어볼 아서도 아니었습니다.\n\n\"...너무 실례가 아니라면... 기억나시나요? 그... 살아계실 적의...\"\n\n차마 말을 매듭짓기는 어려워하는 듯합니다. 아픈 기억일 수도 있고, 미련이 있을 지도 모르고... \n최대한 조심스럽게 다가가야 했는데, 언변에 딱히 소질이 없는 탓에 그는 이렇게 물어보는 수밖에 안 떠올랐습니다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119875","time":"2026-07-17T02:26:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"...기억 안 나시면 딱히 대답 한 해주셔도 돼요. 제가... 제가 실례했네요. 죄송합니다...\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119876","time":"2026-07-17T02:26:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"잠시 추억에 젖은 듯, 조용히 있다가 스르르 입을 엽니다.\n“뭐, 간단히 말씀드리자면 골기아 왕국 수도로부터 동쪽에 있는, 굉장한 구석탱이에 자리한 조그마한, 이름없는 시골 마을에 사는 귀족 집안 아들이었죠. 어릴 적부터 예술 쪽에 두각을 보이는 천재였달까요! 그래서 예술도 하고, 식물학과 연금술도 좀 배워보고, 친구는 많이 없었지만 좋아하는 애도 있었고.. 나름 평범하게 살았죠.“","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119877","time":"2026-07-17T02:33:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"...?\"\n\n귀족 집안과 평범한 삶이라는 말에 뭔가 좋지 못한 느낌을 받은 듯한 아서. \n시선이 살짝 흔들리나 싶더니, 아마이의 모습을 떠올리며 곧 평소로 돌아옵니다.\n\n굳이 자신이 캐묻기 전까지 귀족 출신이라는 점을 아예 듣지 못했으니, 그런 것에 가치를 두지는 않는다고 그는 생각했습니다.\n\n\"...그러셨군요.\"\n\n뭔가 할 말을 찾는 듯합니다. 어쩌면 어떻게 말할지 고민하는 듯도 하군요.\n\n\"...많이 그리우시겠네요... 그 시절이.\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119878","time":"2026-07-17T02:37:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“헹헹, 사실 평범하진 않았죠. 항상 집에만 틀어박혀 지냈으니.\n병 때문에 햇빛 아래에도 못 있고 시한부이기까지 했어서.\n오히려 죽고 언데드가 되서 비로소 사람답게 살 수 있게 됬달까요?\n…..\n물론 사람이었을 때가 그리울 때도 꽤 있지만,\n이런 곳에서, 아서 씨같은 분들과 특별한 경험을 할 수 있으니 지금도 아마이징하게 좋습니다! 헹헹..”\n\n“그러고 보니 아서 씬 뭐하면서 사셨어요? 나이는 몇살이시고?“","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119879","time":"2026-07-17T02:44:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"...!\"\n\n살아 돌아온 시체라. \n가족은 아직 살아계신가. 그렇다면 찾아보러 가셨을까.\n아니라면 왜 자신만 살아 돌아왔는지 원망하지는 않으실까...\n\n아니, 궁금하다고 다 묻는 것은 기사답지 못하다. \n그런 것은 아마이 씨가 나누고 싶다면 이야기를 꺼내거나 하셨을 것이다.\n\n다만 지금, 그의 모험가의 삶이 행복한가. 그게 알고 싶은 것이었을지도.\n\n아마이의 말을 듣고는 충분히 궁금증이 풀린 듯했다. \n\n\"...듣기 좋네요. 감사합니다.\"\n\n* \n\n\"아, 저야 잡일 하면서 커왔죠. 마을 어르신들 도와드리고... 대부분 농사일이었지만 이것저것 힘쓰는 일이면 제가 했죠.\"\n\n몸을 뒤로 젖혀 땅에 누워 밤하늘을 바라봅니다.\n\n\"기사단에서 거절당한 후에는... 사람 도우면서 살 길을 찾다가, 여기 어설픈 용맹 이야기를 듣고 찾아왔어요.\"\n\n고개를 잠시 돌려 나이를 묻는 아마이를 올려다봅니다.\n\n\"열여ㅅ... 아, 아니지. 네 밤 전에... 그럼 이제 열일곱이겠네요.\"","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119880","time":"2026-07-17T02:51:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“…..히야, 아마이징.”\n진심으로 나온 감탄사였습니다.\n물론 몇 마디 만으로 사람의 인생을 판단할 순 없지만,\n이제껏 봐온 아서의 모습도 그렇고,\n정말 성실하고 착한.. 보기 힘든 타입의 사람이자 세상에 더 많아지면 좋겠는 그런 사람.\n그런 생각이 들었기 때문입니다.\n\n물론 아서가 말한 자신의 인생은, 별거 아닌 인생일지도 모르지만.\n조가 생각하던 아서의 모습과 맞물려, 괜히 조에겐 그가 더욱 좋은 사람처럼 느껴졌습니다.\n저번에 같이 갔었던 의뢰 때를 생각하면,\n조는 혼자 도망치기 바빴는데.\n조보다 두 살 어린 17살 소년이 그토록 대담히 행동했단 것이 또한 놀라웠습니다.\n“참.. 어찌보면 수수하고 밍밍하지만, 은은한 향기를 피우며 꽃피울 준비를 하는 꽃봉오리 같은 인생이군요. 나이도 엄청 어리시네요, 놀랐어요! 전 열아홉이에요, 은근 어리죠? 헹헹.”","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119881","time":"2026-07-17T03:01:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"열아홉...?\"\n\n언데드로 살아온 날을 1년 내지 2년으로 생각한다면, 그 말은 아서 자신의 나이쯤에...\n\n\"아...\"\n\n조용해집니다. 나이가 많을 것은 아니라고 예상했지만 그 정도일 줄은 몰랐습니다.\n\n자신이 내일 죽고 아마이와는 달리 다시 일어나지 못한다면 어떨까 생각이 듭니다.\n모험가가 된 만큼 진짜 그렇게 될지도 모르네요.\n\n아서는 그만큼 자신의 삶을 열심히 살아야 할 것 같이 느꼈습니다.\n\n옆에 아마이 씨처럼 말이죠.\n\n한때 그의 손을 멈칫거리게 했던, 정글의 거대한 두꺼비 괴물의 이미지가 이내 사라집니다.\n그 경험에도 불구하고 온몸을 다쳐가면서 의뢰를 또 나가는 모습을 보니--\n\n\"고마워요, 아마이 씨.\"\n\n청년은 미소와 함께 별을 올려다보다, 이내 그동안 못 잤던 잠이 오기 시작했는지 상체를 일으켜 앉습니다. \n\n\"이만 전 들어가 보... 아, 뭐 하나만 더 물어봐도 될까요?\"\n\n진중한 질문인지 아닌지는 들어봐야 알 듯합니다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119882","time":"2026-07-17T03:02:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"뭔진 잘 모르지만, 아서에게 무언가 도움이 된 것 같은 눈치라 괜히 뿌듯해합니다. 헹헹.\n“물어보세요!“","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119883","time":"2026-07-17T03:04:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"...혹시 아마이 형이라고 불러도 돼요?\"\n\n말을 놓아도 되는가, 묻고 있었다.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119884","time":"2026-07-17T03:05:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“….푸흐, 헹헹헹헹! 좋아, 좋아! 아잇~~ 참..“\n아마이 조는 어깨를 들썩이며 좋아합니다.\n”난 또 뭔가 했네! 어쩜 행동이든 말이든 하나하나 너 같냐…“\n아마이 조는 자연스레 말을 놓습니다.\n편하게 대하기로 한 것 같네요.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119885","time":"2026-07-17T03:09:00+09:00","room":"RP III","name":"아서 나이츠베인","profile":"아서 나이츠베인","identity":"reviewed","type":"dialogue","body":"\"...!\"\n\n아서는 큼지막한 미소를 짓고는 몸을 일으킵니다.\n\n\"알았어, 아마이 형!\"\n\n바지를 털고 기지개를 한 번 핍니다.\n\n\"그럼 내일 봐! 형도 푹 쉬고. 어디 골절 생기면 안 되니까-!\"\n\n아서는 손을 흔들며 숙소 쪽으로 멀어져 갑니다. \n\n언젠가 다시 아마이 형과 함께 임무를 나가기를 기대하며.","characters":["P-9d7bf25dbba3"]},{"id":"RP-III-0119886","time":"2026-07-17T03:11:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"“그래, 너도 푹 쉬어라! 잘 자고~”\n아마이 조도 한동안 앉아있다가, 이내 천천히 일어나 숙소로 향합니다.\n.\n.\n.\n형이라고는, 처음 불리네요.\n기분이 썩 나쁘지만은 않습니다.","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119887","time":"2026-07-17T03:13:00+09:00","room":"RP III","name":"아마이 조","profile":"베어","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5d58655d55ce"]},{"id":"RP-III-0119888","time":"2026-07-17T03:13:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
